using System;using RimWorld;using UnityEngine;using Verse;
namespace ElementalHearts {
 public static class CelestialVfx {
  public const int EffectLimit=128,EchoLimit=32,AdornmentLimit=128,MaxDuration=300;
  public static bool Finite(Vector3 at){return !float.IsNaN(at.x)&&!float.IsNaN(at.y)&&!float.IsNaN(at.z)&&!float.IsInfinity(at.x)&&!float.IsInfinity(at.y)&&!float.IsInfinity(at.z);}
  public static bool Visible(Map map,Vector3 from,Vector3 to){if(map==null||map!=Find.CurrentMap||Find.CameraDriver==null||ElementalHeartsMod.Settings.effectOpacity<=0)return false;var view=Find.CameraDriver.CurrentViewRect.ExpandedBy(10);return view.Contains(from.ToIntVec3())||view.Contains(to.ToIntVec3())||view.Contains(((from+to)*.5f).ToIntVec3());}
  public static int Emit(Pawn p,CelestialEffect effect,Vector3 from,Vector3 to,int duration,float width,float height,Pawn follow=null,int ageOffset=0,float opacity=.8f){if(p==null||!p.Spawned||!Finite(from)||!Finite(to)||!Visible(p.Map,from,to))return 0;return p.Map.GetComponent<MapComponent_CelestialVfx>().Add(effect,from,to,Find.TickManager.TicksGame,duration,width,height,follow,ageOffset,opacity);}
  public static void Ghost(Pawn p,Vector3 at){if(p==null||!p.Spawned||!ElementalHeartsMod.Settings.showAfterimages||!Visible(p.Map,at,at))return;p.Map.GetComponent<MapComponent_CelestialVfx>().Ghost(p,at,Find.TickManager.TicksGame);}
  public static void Manifest(Pawn p,int duration){Emit(p,CelestialEffect.SolarSeal,p.DrawPos,p.DrawPos,duration,2.4f,2.4f,p,0,.45f);Emit(p,CelestialEffect.TravelMotes,p.DrawPos,p.DrawPos,duration,2,2,p,0,.45f);Emit(p,CelestialEffect.ArrivalBeam,p.DrawPos,p.DrawPos,duration,1.8f,3.8f,p,0,.38f);}
 }
 public sealed partial class MapComponent_CelestialVfx:MapComponent {
  struct Effect {public bool active;public int token,sequence,start,duration,seed;public Vector3 from,to,offset;public float width,height,opacity;public Pawn follow;}
  struct Echo {public bool active,west;public int start;public Vector3 at;public float width,height;public Material body;}
  readonly Effect[] effects=new Effect[CelestialVfx.EffectLimit];readonly Echo[] echoes=new Echo[CelestialVfx.EchoLimit];readonly Pawn[] adornments=new Pawn[CelestialVfx.AdornmentLimit];int effectCursor,echoCursor,adornCursor,nextToken;MaterialPropertyBlock block;static Mesh beam;
  public MapComponent_CelestialVfx(Map map):base(map){}
  public int Add(CelestialEffect effect,Vector3 from,Vector3 to,int now,int duration,float width,float height,Pawn follow=null,int ageOffset=0,float opacity=.8f){
   if((int)effect<0||(int)effect>=20||!CelestialVfx.Finite(from)||!CelestialVfx.Finite(to)||float.IsNaN(width)||float.IsInfinity(width)||float.IsNaN(height)||float.IsInfinity(height)||float.IsNaN(opacity)||float.IsInfinity(opacity))return 0;
   duration=Math.Max(1,Math.Min(CelestialVfx.MaxDuration,duration));ageOffset=Math.Max(0,ageOffset);if(ageOffset>=duration)return 0;if(++nextToken<=0)nextToken=1;effects[effectCursor]=new Effect{active=true,token=nextToken,sequence=(int)effect,seed=CelestialLightMath.Seed((int)effect,now-ageOffset,from),from=from,to=to,start=now-ageOffset,duration=duration,width=Mathf.Clamp(width,.05f,16),height=Mathf.Clamp(height,.05f,32),opacity=Mathf.Clamp01(opacity),follow=follow,offset=follow!=null?from-follow.DrawPos:Vector3.zero};effectCursor=(effectCursor+1)%effects.Length;return nextToken;
  }
  public void Stop(int token){if(token<=0)return;for(int i=0;i<effects.Length;i++)if(effects[i].active&&effects[i].token==token){effects[i]=new Effect();return;}}
  public void Track(Pawn p){if(p==null)return;for(int i=0;i<adornments.Length;i++)if(adornments[i]==p)return;adornments[adornCursor]=p;adornCursor=(adornCursor+1)%adornments.Length;}
  public void Ghost(Pawn p,Vector3 at,int now){if(p==null||!p.Spawned||!CelestialVfx.Finite(at))return;float w=1,h=1;if(CourtAppearance.WearingKit(p))CourtAppearance.Echo(p,ref w,ref h);else CelestialArmorFit.Echo(p,ref at,ref w,ref h);echoes[echoCursor]=new Echo{active=true,start=now,at=at,width=w,height=h,west=p.Rotation==Rot4.West,body=CelestialVisualAssets.Body(p)};echoCursor=(echoCursor+1)%echoes.Length;}
  bool Live(Pawn p){return p!=null&&p.Spawned&&p.Map==map&&!p.Dead&&!p.Downed;}
  public void Forget(Pawn p){for(int i=0;i<adornments.Length;i++)if(adornments[i]==p)adornments[i]=null;for(int i=0;i<effects.Length;i++)if(effects[i].follow==p)effects[i]=new Effect();}
  public override void FinalizeInit(){Array.Clear(effects,0,effects.Length);Array.Clear(echoes,0,echoes.Length);Array.Clear(adornments,0,adornments.Length);foreach(var p in map.mapPawns.AllPawnsSpawned)if(CelestialAscendant.Active(p))Track(p);}
  public override void MapComponentTick(){int now=Find.TickManager.TicksGame;if(now%15!=0)return;for(int i=0;i<effects.Length;i++)if(effects[i].active&&(now-effects[i].start>=effects[i].duration||effects[i].follow!=null&&!Live(effects[i].follow)))effects[i]=new Effect();for(int i=0;i<echoes.Length;i++)if(echoes[i].active&&now-echoes[i].start>=14)echoes[i]=new Echo();for(int i=0;i<adornments.Length;i++)if(adornments[i]!=null&&(!Live(adornments[i])||!CelestialAscendant.Active(adornments[i])))adornments[i]=null;}
  static Mesh Beam(){if(beam!=null)return beam;float offset=210f/256f-.5f;beam=new Mesh{name="Celestial beam grounded at exported anchor"};beam.vertices=new[]{new Vector3(-.5f,0,-.5f+offset),new Vector3(-.5f,0,.5f+offset),new Vector3(.5f,0,.5f+offset),new Vector3(.5f,0,-.5f+offset)};beam.uv=new[]{new Vector2(0,0),new Vector2(0,1),new Vector2(1,1),new Vector2(1,0)};beam.triangles=new[]{0,1,2,0,2,3};beam.RecalculateNormals();beam.RecalculateBounds();return beam;}
  void Draw(Material mat,Vector3 at,float w,float h,float angle,float opacity,bool floor,bool upright=false){var cell=at.ToIntVec3();if(!cell.InBounds(map)||cell.Fogged(map))return;float alpha=opacity*ElementalHeartsMod.Settings.effectOpacity;if(alpha<=.001f)return;at.y=(floor?AltitudeLayer.MoteLow:AltitudeLayer.MoteOverhead).AltitudeFor();block.SetColor(ShaderPropertyIDs.Color,new Color(1,1,1,alpha));Graphics.DrawMesh(upright?Beam():MeshPool.plane10,Matrix4x4.TRS(at,Quaternion.AngleAxis(angle,Vector3.up),new Vector3(w,1,h)),mat,0,null,0,block);}
  public override void MapComponentDraw(){accentRemaining=CelestialLightMath.AccentLimit;
   if(map!=Find.CurrentMap||Find.CameraDriver==null||ElementalHeartsMod.Settings.effectOpacity<=0)return;if(block==null)block=new MaterialPropertyBlock();int now=Find.TickManager.TicksGame;var view=Find.CameraDriver.CurrentViewRect.ExpandedBy(12);accentView=view;
   for(int i=0;i<effects.Length;i++){var e=effects[i];if(!e.active)continue;int age=now-e.start;if(age<0||age>=e.duration){effects[i]=new Effect();continue;}if(e.follow!=null){if(!Live(e.follow)){effects[i]=new Effect();continue;}e.from=e.to=e.follow.DrawPos+e.offset;}bool trail=e.sequence==1||e.sequence==10;var at=e.sequence==0?Vector3.Lerp(e.from,e.to,Mathf.Clamp01(age/(float)e.duration)):trail?(e.from+e.to)*.5f:e.from;if(!view.Contains(at.ToIntVec3()))continue;float w=trail?Math.Max(.5f,(e.to-e.from).magnitude+.6f):e.width,h=trail?.9f:e.height,angle=trail||e.sequence==0||e.sequence==11?(e.to-e.from).AngleFlat()-90:0;bool floor=trail||e.sequence==3||e.sequence==6||e.sequence==12||e.sequence==15;bool upright=e.sequence==4||e.sequence==13||e.sequence==14;float fade=Math.Min(1,(e.duration-age)/6f);Draw(CelestialVisualAssets.Frame(e.sequence,CelestialVisualAssets.FrameIndex(e.sequence,age,e.duration)),at,w,h,angle,e.opacity*fade,floor,upright);DrawAccents(e,at,age);}
   for(int i=0;i<echoes.Length;i++){var e=echoes[i];if(!e.active)continue;float age=(now-e.start)/14f;if(age>=1){echoes[i]=new Echo();continue;}if(view.Contains(e.at.ToIntVec3()))Draw(e.body,e.at,e.west?-e.width:e.width,e.height,0,.28f*(1-age)*(1-age),false);}
   if(!ElementalHeartsMod.Settings.showAura)return;
   for(int i=0;i<adornments.Length;i++){var p=adornments[i];if(!Live(p)||!view.Contains(p.Position)||!CelestialVisualAssets.AdornmentsVisible(CelestialAscendant.Active(p),HediffComp_ElementalTransform.Active(p),p.Drafted,HediffComp_ElementalTransform.Transforming(p),p.Awake()))continue;float life=Mathf.Clamp(Mathf.Sqrt(p.ageTracker.CurLifeStage.bodySizeFactor),.55f,1.25f);int frame=(now/7+p.thingIDNumber)%6;var at=p.DrawPos;at.z+=.5f*life;Draw(CelestialVisualAssets.Frame(19,frame),at,2.25f*life,2.25f*life,0,.20f,true);at=p.DrawPos+p.Drawer.renderer.BaseHeadOffsetAt(p.Rotation);at.z+=(.4f+.015f*Mathf.Sin(now*.045f))*life;Draw(CelestialVisualAssets.Frame(18,frame),at,.95f*life,.78f*life,0,.28f,false);}
  }
 }
}
